/** The single native window keeps its routing identity across full app exits.
 * Generated by the main process, separate from renderer preferences or credentials.
 */
import { randomUUID } from "node:crypto";
import { closeSync, constants, fstatSync, fsyncSync, openSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

export function loadDesktopClientId(userData: string): string {
	const path = join(userData, "client-identity");
	let fd: number;
	try {
		fd = openSync(path, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
		const id = randomUUID();
		fd = openSync(path, "wx", 0o600);
		try {
			writeFileSync(fd, `${id}\n`);
			fsyncSync(fd);
		} finally {
			closeSync(fd);
		}
		if (process.platform !== "win32") {
			const dir = openSync(userData, "r");
			try {
				fsyncSync(dir);
			} finally {
				closeSync(dir);
			}
		}
		return id;
	}
	try {
		const stat = fstatSync(fd);
		if (!stat.isFile() || stat.size > 128) throw new Error("Invalid desktop client identity file");
		const id = readFileSync(fd, "utf8").trim();
		if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(id))
			throw new Error("Invalid desktop client identity; restore the original userData backup");
		return id;
	} finally {
		closeSync(fd);
	}
}
